'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var dnthIndexOf = tryRequire( resolve( __dirname, './../lib/dnth_index_of.native.js' ) );
var opts = {
	'skip': ( dnthIndexOf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dnthIndexOf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', opts, function test( t ) {
	t.strictEqual( dnthIndexOf.length, 5, 'returns expected value' );
	t.end();
});

tape( 'the function returns the index of the n-th occurrence of an element which equals a provided search element', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	// First occurrence...
	actual = dnthIndexOf( x.length, 1, 1.0, x, 1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = dnthIndexOf( x.length, 1, 2.0, x, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	actual = dnthIndexOf( x.length, 1, 3.0, x, 1 );
	t.strictEqual( actual, 4, 'returns expected value' );

	// Second occurrence...
	actual = dnthIndexOf( x.length, 2, 1.0, x, 1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	actual = dnthIndexOf( x.length, 2, 2.0, x, 1 );
	t.strictEqual( actual, 3, 'returns expected value' );

	actual = dnthIndexOf( x.length, 2, 3.0, x, 1 );
	t.strictEqual( actual, 5, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = dnthIndexOf( x.length, 1, 3.0, x, -1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = dnthIndexOf( x.length, 2, 3.0, x, -1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	actual = dnthIndexOf( x.length, 1, 1.0, x, -1 );
	t.strictEqual( actual, 4, 'returns expected value' );

	actual = dnthIndexOf( x.length, 2, 1.0, x, -1 );
	t.strictEqual( actual, 5, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if unable to find the n-th occurrence of a search element', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	// Search element which is not present...
	actual = dnthIndexOf( x.length, 1, 4.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	// Occurrence number which exceeds the number of matching elements...
	actual = dnthIndexOf( x.length, 3, 1.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if provided an `N` parameter which is less than or equal to zero', opts, function test( t ) {
	var actual;

	actual = dnthIndexOf( 0, 1, 2.0, new Float64Array( [ 1.0, 2.0, 3.0 ] ), 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dnthIndexOf( -1, 1, 2.0, new Float64Array( [ 1.0, 2.0, 3.0 ] ), 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if provided a `k` parameter which is less than or equal to zero', opts, function test( t ) {
	var actual;

	actual = dnthIndexOf( 3, 0, 2.0, new Float64Array( [ 1.0, 2.0, 3.0 ] ), 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dnthIndexOf( 3, -1, 2.0, new Float64Array( [ 1.0, 2.0, 3.0 ] ), 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if provided a search element equal to `NaN`', opts, function test( t ) {
	var actual;

	actual = dnthIndexOf( 1, 1, NaN, new Float64Array( [ NaN ] ), 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});
